s=s.replace(marker,addition+'\n'+marker)
# secure public wallet endpoint: don't expose another user's balance without signed initData
old="app.get('/api/wallet/:userId',(req,res)=>{const d=readData(),id=userKey(req.params.userId);res.json({userId:id,balance:Number((d.wallets||{})[id]||0),points:Number((d.loyalty||{})[id]||0)});});"
new="app.get('/api/wallet/:userId',(req,res)=>{const id=userKey(req.params.userId),verified=verifyTelegramInitData(String(req.query.initData||''));if(!verified||verified!==id)return res.status(401).json({error:'برای مشاهده کیف پول، هویت تلگرام همین کاربر باید تأیید شود.'});const d=readData();res.json({userId:id,balance:Number((d.wallets||{})[id]||0),points:Number((d.loyalty||{})[id]||0)});});"
if old in s:s=s.replace(old,new)
# improve spin eligibility: requires at least one paid order, one spin per eligible paid order; backward-compatible only when there is an approved order
