new2="const eligibleOrders=(data.orders||[]).filter(o=>String(o.telegramUserId||'')===uid&&['approved','fulfilled'].includes(o.status)); if(!eligibleOrders.length)return res.status(403).json({error:'برای چرخاندن گردونه ابتدا باید یک سفارش پرداخت‌شده داشته باشی.'}); data.roulette.spins=data.roulette.spins||{}; const used=Number(data.roulette.spins[uid]?.count||0); if(used>=eligibleOrders.length)return res.status(409).json({error:'برای هر سفارش تأییدشده فقط یک نوبت گردونه مجاز است.',prize:data.roulette.spins[uid]?.prize});\n  const prizes"
if old2 in s:s=s.replace(old2,new2)
s=s.replace("data.roulette.spins[uid] = { prize: prize.label, at: new Date().toISOString() }; saveData(data);","data.roulette.spins[uid] = { prize: prize.label, at: new Date().toISOString(), count: used+1, orderId: eligibleOrders[used]?.id || null }; audit(data,'roulette.spun',{userId:uid,prize:prize.label,orderId:eligibleOrders[used]?.id||null}); saveData(data);")
